const SC={};function stat(k,v){SC[k]=(SC[k]||0)+v}
let lastS=null;
function flush(Sx,why){try{const D=Sx&&Sx._dr;if(!D||D.sent)return;D.sent=1;const f=Math.min(9,Math.floor(((Sx.age|0)/Math.max(30,+Sx.lifespan||80))*10));
 const c=Object.assign({},SC);c[(why==='q'?'q':'d')+f]=1;c.pkL=Math.min(30,D.n);c.omL=Math.min(30,D.om);c.ffL=Math.min(30,D.ff);if(D.loss)c.lsL=Math.min(30,D.loss);
 for(const k in SC)delete SC[k];if(typeof api==='function'&&typeof onlineOK!=='undefined'&&onlineOK)api('drs',{c}).catch(()=>{})}catch(e){}}
setInterval(()=>{try{if(lastS&&lastS!==S)flush(lastS,lastS.alive?'q':'d');if(S&&S._dr&&!S.alive)flush(S,'d');
 const t=document.getElementById('title');if(S&&S.alive&&S._dr&&t&&t.classList.contains('on')&&!S._dr.qq){S._dr.qq=1;stat('tq',1)}lastS=S}catch(e){}},3000);
window.addEventListener('pagehide',()=>{try{if(S&&S._dr&&S.alive)flush(S,'q')}catch(e){}});

